function FormatNumber(value) {
    if (value === undefined || value === null || !isFinite(value)) {
        return "--";
    }
    const rounded = Math.round(value * 100) / 100;
    return Number.isInteger(rounded) ? String(rounded) : String(rounded.toFixed(2));
}

function SetScenePanelUnit(panel, unitName) {
    if (!panel || !unitName) return;
    if (panel._lastUnitName === unitName) {
        return;
    }
    panel._lastUnitName = unitName;
    if (!panel._sceneSet && panel.SetScene) {
        panel.SetScene("scenes/ui/hero_card/hero_card.vmap");
        panel._sceneSet = true;
    }
    if (panel.SetUnit) {
        panel.SetUnit(unitName, "idle", false);
    }
}

