}

function NormalizeShop1DummyPayload(event) {
    const unitName = event && event.unit_name ? event.unit_name : "";
    const modelUnitName = event && event.model_unit_name ? event.model_unit_name : unitName;
    return {
        ability: event && event.ability ? event.ability : "",
        entindex: event && event.entindex !== undefined ? event.entindex : -1,
        selection_proxy_entindex: event && event.selection_proxy_entindex !== undefined ? event.selection_proxy_entindex : -1,
        unit_name: unitName,
        model_unit_name: modelUnitName,
        attack_final: event && event.attack_final !== undefined ? event.attack_final : 0,
        career: event && event.career ? event.career : "",
        career_icon: event && event.career_icon ? event.career_icon : "",
        projectile_name: event && event.projectile_name ? event.projectile_name : "",
        projectile_interval: event && event.projectile_interval !== undefined ? event.projectile_interval : 0,
        description_token: event && event.description_token ? event.description_token : "",
        description_vars: event && event.description_vars ? event.description_vars : {}
    };
}

function BuildShop1DummyPayloadHash(data) {
    const vars = data && data.description_vars ? data.description_vars : {};
    const keys = Object.keys(vars).sort();
    const varsText = keys.map((key) => key + ":" + String(vars[key])).join("|");
    return [
        data.ability,
        data.unit_name,
        data.model_unit_name,
        data.attack_final,
        data.career,
        data.career_icon,
        data.projectile_name,
        data.projectile_interval,
        data.description_token,
        varsText
    ].join("#");
}

function ApplyShop1DummyPayload(data) {
    const hash = BuildShop1DummyPayloadHash(data);
    const changed = hash !== g_SelectedShop1PayloadHash;

    g_SelectedShop1PayloadHash = hash;
    g_SelectedShop1Ability = data.ability;
    g_SelectedShop1Ent = data.entindex;
    g_SelectedShop1ProxyEnt = data.selection_proxy_entindex;
    g_SelectedShop1UnitName = data.unit_name;
    g_SelectedShop1ModelUnitName = data.model_unit_name;
    g_SelectedShop1Attack = data.attack_final;
    g_SelectedShop1Career = data.career;
    g_SelectedShop1CareerIcon = data.career_icon;
    g_SelectedShop1ProjectileName = data.projectile_name;
    g_SelectedShop1Cooldown = data.projectile_interval;
    g_SelectedShop1DescriptionToken = data.description_token;
    g_SelectedShop1DescriptionVars = data.description_vars;

    return changed;
}

function UpdateShop1DummyPanel() {
    if (!g_SelectedShop1Ability || g_SelectedShop1Ent === -1) {
        return;
    }

    const model = $("#Shop1DummyModel");
    if (model && g_SelectedShop1ModelUnitName) {
        SetScenePanelUnit(model, g_SelectedShop1ModelUnitName);
    }

    const nameLabel = $("#Shop1DummyName");
    if (nameLabel) {
        const token = g_SelectedShop1UnitName ? "#" + g_SelectedShop1UnitName : "";
        const localized = token ? $.Localize(token) : "";
        nameLabel.text = localized && localized.indexOf("#") !== 0 ? localized : (g_SelectedShop1UnitName || "--");
    }

    const attackIcon = $("#Shop1DummyAttackIcon");
    if (attackIcon) {
        SetPanelImage(attackIcon, "panorama/images/control_icons/24px/attack_damage.vsvg_c");
    }
    const attackValue = $("#Shop1DummyAttackValue");
    if (attackValue) {
        attackValue.text = FormatNumber(g_SelectedShop1Attack);
    }

    const careerIcon = $("#Shop1DummyCareerIcon");
    if (careerIcon) {
        if (g_SelectedShop1CareerIcon) {
            SetPanelImage(careerIcon, g_SelectedShop1CareerIcon);
            careerIcon.visible = true;
        } else {
            careerIcon.SetImage("");
            careerIcon.visible = false;
        }
    }
    const careerText = $("#Shop1DummyCareerText");
    if (careerText) {
        const token = g_SelectedShop1Career ? "#" + g_SelectedShop1Career : "";
        const localized = token ? $.Localize(token) : "";
        careerText.text = localized && localized.indexOf("#") !== 0 ? localized : (g_SelectedShop1Career || "--");
    }

    const projName = $("#Shop1DummyProjectileName");
    if (projName) {
        const token = g_SelectedShop1ProjectileName ? "#" + g_SelectedShop1ProjectileName : "";
        const localized = token ? $.Localize(token) : "";
        projName.text = localized && localized.indexOf("#") !== 0 ? localized : (g_SelectedShop1ProjectileName || "--");
    }

    const cooldown = $("#Shop1DummyCooldown");
    if (cooldown) {
        const cd = FormatNumber(g_SelectedShop1Cooldown);
        const label = GetStatLabel("ProjectileInterval");
        cooldown.text = label + "：" + cd + "s";
    }

    const desc = $("#Shop1DummyDesc");
    const row = $("#Shop1DummyRow");
    if (desc) {
        if (g_SelectedShop1DescriptionVars) {
            for (const key of Object.keys(g_SelectedShop1DescriptionVars)) {
                const value = String(g_SelectedShop1DescriptionVars[key]);
                desc.SetDialogVariable(key, value);
                if (row) {
                    row.SetDialogVariable(key, value);
                }
            }
        }
        if (g_SelectedShop1DescriptionToken) {
            const token = g_SelectedShop1DescriptionToken[0] === "#"
                ? g_SelectedShop1DescriptionToken
                : "#" + g_SelectedShop1DescriptionToken;
            let text = $.Localize(token, row || desc);
            if (g_SelectedShop1DescriptionVars) {
                for (const key of Object.keys(g_SelectedShop1DescriptionVars)) {
                    const value = String(g_SelectedShop1DescriptionVars[key]);
                    const re = new RegExp("%" + key + "%", "g");
                    text = text.replace(re, value);
                }
            }
            desc.text = text;
        } else {
            desc.text = "";
        }
    }
}

